// Pane MCP server: lets a coding agent (Claude Code, Codex, Cursor) search Pane and pull a piece's source.
//
//   claude mcp add --transport http pane https://paneui.vercel.app/api/mcp
//
// Streamable HTTP, stateless: every request is one JSON-RPC message (or a batch) answered with JSON.
// The catalog is generated by scripts/build-llms.py; piece sources come from this site's own /r/<slug>.json.
import catalog from "./_catalog.json" with { type: "json" }

type Piece = (typeof catalog.pieces)[number]
type Skill = (typeof catalog.skills)[number]
type Json = Record<string, unknown>
type RpcRequest = { jsonrpc: "2.0"; id?: string | number | null; method: string; params?: Json }

const VERSIONS = ["2025-06-18", "2025-03-26", "2024-11-05"]
const SERVER = { name: "pane", title: "Pane", version: "1.0.0" }
const INSTRUCTIONS = `Pane is an open-source library of one-file React + Tailwind pieces for AI and agent products: components, blocks, illustrations, motion effects and full screens, each with light/dark, a Glass and a Mono style, keyboard support and a live demo. Use search_pieces to find pieces for a job (e.g. "approve an agent action", "streaming answer", "bottom sheet"), get_piece for the source and install command, and get_guide for the house style before composing a page.`

const KINDS = ["component", "block", "illustration", "motion effect"]
const GUIDES: Record<string, string> = {
  skill: "/skills/pane.md",
  look: "/skills/pane/look.md",
  build: "/skills/pane/build.md",
  glass: "/skills/pane/glass.md",
  instrument: "/skills/pane/instrument.md",
  "hand-drawn": "/skills/pane/hand-drawn.md",
  catalog: "/skills/pane/catalog.md",
}

const TOOLS = [
  {
    name: "search_pieces",
    title: "Search Pane",
    description: "Search Pane's pieces by job, interaction or look (e.g. 'agent approval', 'drag to dismiss', 'grainy gradient'). Returns slugs with descriptions, tags and install commands, best match first.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "What you need, in plain words." },
        kind: { type: "string", enum: KINDS, description: "Only this kind of piece." },
        tag: { type: "string", description: "Only pieces with this tag (see list_tags), e.g. drag, glass, agent." },
        limit: { type: "integer", minimum: 1, maximum: 25, default: 8 },
      },
      required: ["query"],
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "get_piece",
    title: "Get a piece",
    description: "Everything about one piece: what it does, tags, install commands, its live page and the full .tsx source (one self-contained file with its own CSS).",
    inputSchema: {
      type: "object",
      properties: {
        slug: { type: "string", description: "The piece slug, e.g. 'odometer'." },
        source: { type: "boolean", default: true, description: "Include the full source file." },
      },
      required: ["slug"],
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "list_pieces",
    title: "List pieces",
    description: "List every piece, grouped as on the site (Originals, Overlays, Stage, Chat, Agents, Charts, Illustrations, Motion…). Filter by group or kind.",
    inputSchema: {
      type: "object",
      properties: { group: { type: "string" }, kind: { type: "string", enum: KINDS } },
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "list_tags",
    title: "List tags",
    description: "The tag vocabulary (jobs, AI concepts, interactions, looks) with what each means and how many pieces carry it.",
    inputSchema: { type: "object", properties: {} },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "get_guide",
    title: "Read the house style",
    description: "Pane's own guidance: 'skill' (overview), 'look' (tokens, type, motion), 'build' (how a piece is made), 'glass' (the Liquid Glass recipe), 'instrument' (the Instrument kit look), 'hand-drawn' (canvas art that looks drawn with pastel, crayon and pencil, plus the emotion-brief prompt) or 'catalog' (the full catalog with recipes per page type).",
    inputSchema: {
      type: "object",
      properties: { topic: { type: "string", enum: Object.keys(GUIDES) } },
      required: ["topic"],
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "search_skills",
    title: "Search agent skills",
    description: "Search the curated list of agent skills for UI work (design taste, motion, gestures, accessibility, video…) with their install commands.",
    inputSchema: {
      type: "object",
      properties: { query: { type: "string" }, category: { type: "string" }, limit: { type: "integer", minimum: 1, maximum: 25, default: 8 } },
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
]

/* ----------------------------------- Search ---------------------------------- */

const norm = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
const words = (s: string) => norm(s).split(" ").filter((w) => w.length > 1)

function near(a: string, b: string) {
  if (a === b) return true
  if (Math.abs(a.length - b.length) > 1 || a.length < 5) return false
  let edits = 0
  for (let i = 0, j = 0; i < a.length || j < b.length; i++, j++) {
    if (a[i] === b[j]) continue
    if (++edits > 1) return false
    if (a.length > b.length) j--
    else if (b.length > a.length) i--
  }
  return true
}

/** The query's words plus tags their synonyms point to ("modal" also finds "dialog"). */
function expand(query: string) {
  const ws = words(query)
  const syn = catalog.synonyms as Record<string, string[]>
  const extra = new Set<string>()
  const q = norm(query)
  for (const [term, tags] of Object.entries(syn)) if (q.includes(norm(term))) tags.forEach((t) => extra.add(t))
  return { ws, extra: [...extra] }
}

function score(p: Piece, ws: string[], extra: string[]) {
  const fields: [string, number][] = [
    [p.name, 10],
    [p.slug.replace(/-/g, " "), 9],
    [p.tags.join(" "), 6],
    [p.keywords.join(" "), 5],
    [p.group, 3],
    [p.description, 2],
  ]
  let s = 0
  for (const w of ws) {
    let best = 0
    for (const [text, weight] of fields) {
      const tw = words(text)
      if (tw.includes(w)) best = Math.max(best, weight)
      else if (tw.some((t) => t.startsWith(w) && w.length >= 3)) best = Math.max(best, weight * 0.7)
      else if (tw.some((t) => near(t, w))) best = Math.max(best, weight * 0.5)
    }
    s += best
  }
  for (const t of extra) if (p.tags.includes(t)) s += 4
  // Every word should matter: reward matching all of them.
  if (ws.length > 1 && ws.every((w) => norm(`${p.name} ${p.slug} ${p.tags.join(" ")} ${p.keywords.join(" ")} ${p.description}`).includes(w))) s *= 1.4
  return s
}

const install = (p: Piece, site: string) =>
  p.inRegistry
    ? { shadcn: `npx shadcn@latest add ${site}/r/${p.slug}.json`, anyProject: `curl -sO ${site}/add.mjs && node add.mjs ${p.slug}` }
    : null

const line = (p: Piece, site: string) =>
  `- ${p.name} (\`${p.slug}\`, ${p.kind}, ${p.group}) – ${p.description}\n  tags: ${p.tags.join(", ") || "none"} · ${p.inRegistry ? `install: npx shadcn@latest add ${site}/r/${p.slug}.json` : "not in the registry"} · ${site}/#/${p.slug}`

/* ----------------------------------- Tools ----------------------------------- */

const text = (t: string, isError = false) => ({ content: [{ type: "text", text: t }], ...(isError ? { isError: true } : {}) })

async function callTool(name: string, args: Json, origin: string) {
  const site = catalog.site
  const pieces = catalog.pieces as Piece[]
  if (name === "search_pieces") {
    const query = String(args.query ?? "").trim()
    if (!query) return text("Give a query, e.g. 'approve an agent action'.", true)
    const limit = Math.min(25, Math.max(1, Number(args.limit ?? 8)))
    const { ws, extra } = expand(query)
    const hits = pieces
      .filter((p) => (!args.kind || p.kind === args.kind) && (!args.tag || p.tags.includes(String(args.tag))))
      .map((p) => ({ p, s: score(p, ws, extra) }))
      .filter((h) => h.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, limit)
    if (!hits.length) return text(`No pieces match "${query}". Try other words, or list_tags / list_pieces to browse.`)
    return text(`${hits.length} match${hits.length > 1 ? "es" : ""} for "${query}":\n${hits.map((h) => line(h.p, site)).join("\n")}\n\nUse get_piece with a slug for its source.`)
  }
  if (name === "get_piece") {
    const slug = String(args.slug ?? "").trim().toLowerCase()
    const p = pieces.find((x) => x.slug === slug)
    if (!p) {
      const { ws, extra } = expand(slug.replace(/-/g, " "))
      const guess = pieces.map((x) => ({ x, s: score(x, ws, extra) })).sort((a, b) => b.s - a.s).slice(0, 3)
      return text(`No piece called "${slug}". Did you mean: ${guess.map((g) => g.x.slug).join(", ")}?`, true)
    }
    const how = install(p, site)
    const head = [
      `# ${p.name} (\`${p.slug}\`)`,
      p.description,
      `Kind: ${p.kind} · Group: ${p.group} · Tags: ${p.tags.join(", ")}`,
      `Live demo: ${site}/#/${p.slug}`,
      how ? `Install (shadcn project): ${how.shadcn}\nInstall (any React project): ${how.anyProject}` : "Not in the registry yet: copy the source below.",
      `File: ${p.file} – one self-contained file (its CSS is a <style> inside). Works with no props; read its exported types for real data.`,
    ].join("\n")
    if (args.source === false || !p.inRegistry) return text(head)
    try {
      const res = await fetch(`${origin}/r/${p.slug}.json`)
      if (!res.ok) throw new Error(String(res.status))
      const item = (await res.json()) as { files?: { content?: string; target?: string }[]; dependencies?: string[] }
      const file = item.files?.[0]
      const deps = item.dependencies?.length ? `\nnpm dependencies: ${item.dependencies.join(", ")}` : ""
      return text(`${head}${deps}\n\n\`\`\`tsx\n// ${file?.target ?? p.file}\n${file?.content ?? ""}\n\`\`\``)
    } catch (e) {
      return text(`${head}\n\nCouldn't load the source right now (${(e as Error).message}). Install it with the command above.`)
    }
  }
  if (name === "list_pieces") {
    const list = pieces.filter((p) => (!args.group || p.group.toLowerCase() === String(args.group).toLowerCase()) && (!args.kind || p.kind === args.kind))
    if (!list.length) return text(`Nothing matches. Groups: ${[...new Set(pieces.map((p) => p.group))].join(", ")}.`)
    const groups = new Map<string, Piece[]>()
    for (const p of list) groups.set(p.group, [...(groups.get(p.group) ?? []), p])
    return text(
      [...groups].map(([g, ps]) => `## ${g} (${ps.length})\n${ps.map((p) => `- \`${p.slug}\` ${p.name} – ${p.description}`).join("\n")}`).join("\n\n"),
    )
  }
  if (name === "list_tags") {
    const counts = new Map<string, number>()
    for (const p of pieces) for (const t of p.tags) counts.set(t, (counts.get(t) ?? 0) + 1)
    const vocab = catalog.vocab as { tag: string; facet: string; meaning: string }[]
    const byFacet = new Map<string, string[]>()
    for (const v of vocab) byFacet.set(v.facet, [...(byFacet.get(v.facet) ?? []), `- ${v.tag} (${counts.get(v.tag) ?? 0}) – ${v.meaning}`])
    return text([...byFacet].map(([f, ls]) => `## ${f}\n${ls.join("\n")}`).join("\n\n"))
  }
  if (name === "get_guide") {
    const path = GUIDES[String(args.topic)]
    if (!path) return text(`Topics: ${Object.keys(GUIDES).join(", ")}.`, true)
    const res = await fetch(`${origin}${path}`)
    return res.ok ? text(await res.text()) : text(`Couldn't load the guide (${res.status}). Read it at ${site}${path}.`, true)
  }
  if (name === "search_skills") {
    const skills = catalog.skills as Skill[]
    const limit = Math.min(25, Math.max(1, Number(args.limit ?? 8)))
    const ws = words(String(args.query ?? ""))
    const list = skills
      .filter((s) => !args.category || (s.category ?? "").toLowerCase() === String(args.category).toLowerCase())
      .map((s) => {
        const hay = norm(`${s.name} ${s.id} ${s.description} ${s.category} ${(s.bestFor ?? []).join(" ")}`)
        return { s, n: ws.length ? ws.filter((w) => hay.includes(w)).length : 1 }
      })
      .filter((x) => x.n > 0)
      .sort((a, b) => b.n - a.n)
      .slice(0, limit)
    if (!list.length) return text(`No skills match. Categories: ${[...new Set(skills.map((s) => s.category))].join(", ")}.`)
    return text(list.map(({ s }) => `- ${s.name} (${s.category}) – ${s.description}\n  install: ${s.install ?? "see repo"} · ${s.repo ?? ""}`).join("\n"))
  }
  return text(`Unknown tool "${name}".`, true)
}

/* ---------------------------------- Protocol --------------------------------- */

const ok = (id: RpcRequest["id"], result: unknown) => ({ jsonrpc: "2.0", id, result })
const fail = (id: RpcRequest["id"], code: number, message: string) => ({ jsonrpc: "2.0", id: id ?? null, error: { code, message } })

async function handle(msg: RpcRequest, origin: string) {
  if (!msg || msg.jsonrpc !== "2.0" || typeof msg.method !== "string") return fail(msg?.id, -32600, "Invalid request")
  const isNotification = msg.id === undefined
  switch (msg.method) {
    case "initialize": {
      const asked = String(msg.params?.protocolVersion ?? "")
      return ok(msg.id, {
        protocolVersion: VERSIONS.includes(asked) ? asked : VERSIONS[0],
        capabilities: { tools: { listChanged: false } },
        serverInfo: SERVER,
        instructions: INSTRUCTIONS,
      })
    }
    case "ping":
      return ok(msg.id, {})
    case "tools/list":
      return ok(msg.id, { tools: TOOLS })
    case "tools/call": {
      const name = String(msg.params?.name ?? "")
      if (!TOOLS.some((t) => t.name === name)) return fail(msg.id, -32602, `Unknown tool: ${name}`)
      try {
        return ok(msg.id, await callTool(name, (msg.params?.arguments as Json) ?? {}, origin))
      } catch (e) {
        return ok(msg.id, text(`The tool failed: ${(e as Error).message}`, true))
      }
    }
    default:
      return isNotification ? null : fail(msg.id, -32601, `Method not found: ${msg.method}`)
  }
}

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Accept, Mcp-Session-Id, Mcp-Protocol-Version",
}

export async function POST(request: Request) {
  const origin = new URL(request.url).origin
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return Response.json(fail(null, -32700, "Parse error"), { status: 400, headers: CORS })
  }
  const batch = Array.isArray(body)
  const messages = (batch ? body : [body]) as RpcRequest[]
  const replies = (await Promise.all(messages.map((m) => handle(m, origin)))).filter(Boolean)
  // Only notifications: nothing to answer.
  if (!replies.length) return new Response(null, { status: 202, headers: CORS })
  return Response.json(batch ? replies : replies[0], { headers: CORS })
}

export function GET() {
  // No server-initiated stream: this server is stateless and only answers POSTs.
  return new Response("Pane MCP server. POST JSON-RPC here; see https://paneui.vercel.app/#/mcp", {
    status: 405,
    headers: { ...CORS, Allow: "POST, OPTIONS", "Content-Type": "text/plain" },
  })
}

export function OPTIONS() {
  return new Response(null, { status: 204, headers: CORS })
}
